+func recordFactCarryMisses(ctx context.Context, params ActionParams, misses []factCarryMiss) {
+	if len(misses) == 0 { return }
+	siteID := datahelpers.ExtractNestedFieldString(params.CollectedData, "site_record.site_id")
+	for _, m := range misses {
+		LogActionError(ctx, params, siteID, "", "validate_plan",
+			"FACT_CARRY_UNMATCHED_SECTION", "warning",
+			fmt.Sprintf("page %q: %d plan-time fact assignment(s) named a section the realised composition does not contain — discarded", m.Page, len(m.Sections)),
+			map[string]interface{}{
+				"page": m.Page, "unmatched_sections": m.Sections,
+				"remedy": "the planner scoped facts to section names this built page does not have ... (RFC_016 candidate 1b)",
+			}, params.Logger)
+	}
